/* Stardeck service worker — generated by scripts/build-sw.mjs. Do not edit out/sw.js directly. */
const VERSION = '__VERSION__';
const PRECACHE = `stardeck-precache-${VERSION}`;
const RUNTIME = 'stardeck-runtime-v1';
const ASSETS = __ASSETS__;
const PAGES = __PAGES__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(PRECACHE);
      // Fetch fresh copies (bypassing the HTTP cache) so a new version never mixes files.
      await cache.addAll(ASSETS.map((url) => new Request(url, { cache: 'reload' })));
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k.startsWith('stardeck-precache-') && k !== PRECACHE).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

function pageFor(pathname) {
  const clean = pathname.endsWith('/') ? pathname : `${pathname}/`;
  return PAGES.includes(clean) ? clean : null;
}

async function fromPrecache(request, options) {
  const cache = await caches.open(PRECACHE);
  return cache.match(request, options);
}

async function networkFirstPage(request) {
  const url = new URL(request.url);
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 3500);
    const response = await fetch(request, { signal: controller.signal });
    clearTimeout(timer);
    if (response.ok) return response;
    throw new Error(`HTTP ${response.status}`);
  } catch {
    const page = pageFor(url.pathname);
    const cached =
      (page && (await fromPrecache(page, { ignoreSearch: true }))) || (await fromPrecache('/', { ignoreSearch: true }));
    return cached || Response.error();
  }
}

async function cacheFirst(request) {
  const cached = (await fromPrecache(request)) || (await caches.match(request));
  if (cached) return cached;
  const response = await fetch(request);
  if (response.ok) (await caches.open(RUNTIME)).put(request, response.clone());
  return response;
}

async function staleWhileRevalidate(request, options) {
  const cached = (await fromPrecache(request, options)) || (await caches.match(request, options));
  const network = fetch(request)
    .then(async (response) => {
      if (response.ok) (await caches.open(RUNTIME)).put(request, response.clone());
      return response;
    })
    .catch(() => cached || Response.error());
  return cached || network;
}

async function networkFirst(request) {
  try {
    const response = await fetch(request);
    if (response.ok) (await caches.open(RUNTIME)).put(request, response.clone());
    return response;
  } catch {
    return (await caches.match(request)) || (await fromPrecache(request)) || Response.error();
  }
}

/** The router sends HEAD probes for linked pages; answer them from the precache when offline. */
async function headForPage(request) {
  try {
    return await fetch(request);
  } catch {
    const page = pageFor(new URL(request.url).pathname);
    const cached = page && (await fromPrecache(page, { ignoreSearch: true }));
    return cached ? new Response(null, { status: 200, headers: cached.headers }) : new Response(null, { status: 404 });
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (request.method === 'HEAD') {
    event.respondWith(headForPage(request));
    return;
  }
  if (request.method !== 'GET') return;

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstPage(request));
    return;
  }
  if (
    url.pathname.startsWith('/_next/static/') ||
    url.pathname.startsWith('/fonts/') ||
    url.pathname.startsWith('/icons/') ||
    url.pathname.startsWith('/workers/') ||
    // On-device AI model + runtime: downloaded on first use, then served offline.
    url.pathname.startsWith('/ml/')
  ) {
    event.respondWith(cacheFirst(request));
    return;
  }
  if (url.pathname.startsWith('/trends/')) {
    event.respondWith(networkFirst(request));
    return;
  }
  // RSC payloads for client-side navigation (`/page/index.txt?_rsc=…`).
  if (url.pathname.endsWith('.txt')) {
    event.respondWith(staleWhileRevalidate(request, { ignoreSearch: true }));
    return;
  }
  event.respondWith(staleWhileRevalidate(request));
});
